// Generates the Starlight documentation pages from the single source of truth:
// the ReStructuredText files in ../docs/ (plus images and data files next to
// them). The Jupyter notebook pages are generated by generate-notebooks.mjs.
//
// This keeps the documentation authored in exactly one place: docs/ (RST +
// ipynb). The generated Markdown in src/content/docs/ is gitignored and never
// committed, so there is no second copy to keep in sync.
//
// Requirements: `uvx` (local) or `rst2myst` on PATH (pip install rst-to-myst,
// as done by the Read the Docs build and the GitHub Actions workflow).

import { execFileSync, spawnSync } from 'node:child_process';
import { mkdirSync, rmSync, readdirSync, readFileSync, writeFileSync, cpSync, existsSync, statSync } from 'node:fs';
import { resolve, dirname, basename, join, posix } from 'node:path';
import { fileURLToPath } from 'node:url';

const scriptDir = dirname(fileURLToPath(import.meta.url));
const siteDir = resolve(scriptDir, '..');
const repoRoot = execFileSync('git', ['rev-parse', '--show-toplevel'], { cwd: siteDir }).toString().trim();
const docsRoot = resolve(repoRoot, 'docs');
const outRoot = join(siteDir, 'src/content/docs');
const publicGen = join(siteDir, 'public/generated');
const siteConfig = JSON.parse(readFileSync(join(siteDir, 'site.config.json'), 'utf8'));
const notFoundTemplate = readFileSync(join(siteDir, 'site-chrome/404.md'), 'utf8');

const PAGE_SLUGS = new Map([
  ['models', 'models'],
  ['pre_applied_beam', 'pre_applied_beam'],
  ['co_lines', 'co_lines'],
  ['websky', 'websky'],
  ['contributing', 'contributing'],
  ['pysm_methods_author_contributions', 'pysm_methods_author_contributions'],
  ['guides/installation', 'guides/installation'],
  ['guides/usage', 'guides/usage'],
  ['guides/best_practices', 'guides/best_practices'],
  ['api/pysm3', 'api/pysm3'],
]);

// --- Markdown post-processing ----------------------------------------------

function cleanMath(m) {
  return m.replace(/\\([_{}])/g, '$1').replace(/\\\\/g, '\\').trim();
}

function cleanInline(text) {
  return text
    .replace(/\{py:(?:class|func|meth|attr|obj|mod|data|exc|const|var)\}`~?([^`]+)`/g, '`$1`')
    .replace(/:math:`([^`]+)`/g, (_, m) => `$${cleanMath(m)}$`)
    .replace(/:sup:`([^`]+)`/g, '<sup>$1</sup>')
    .replace(/:sub:`([^`]+)`/g, '<sub>$1</sub>')
    .replace(/\\\s/g, ' ');
}

function convertEvalRst(inner, fromPage, docsFiles) {
  if (/\.\. automodapi::/.test(inner)) {
    return 'See the [pysm3 API reference](api/pysm3/).';
  }
  if (/\.\. toctree::/.test(inner)) {
    return convertToctree(inner, fromPage, docsFiles);
  }
  if (/\.\. list-table::/.test(inner)) {
    return convertListTable(inner);
  }
  return '';
}

function convertListTable(inner) {
  const rows = [];
  let current = null;
  for (const rawLine of inner.split('\n')) {
    const line = rawLine.replace(/\s+$/, '');
    if (/^\s*\* -/.test(line)) {
      current = [line.replace(/^\s*\* -\s*/, '')];
      rows.push(current);
    } else if (/^\s*- /.test(line)) {
      if (current) current.push(line.replace(/^\s*- /, ''));
    } else if (/^\s*$/.test(line)) {
      // blank line: keep going
    } else if (current) {
      current[current.length - 1] += ' ' + line.trim();
    }
  }
  const cells = rows.map((row) => row.map((cell) => cleanInline(cell).replace(/\|/g, '\\|').replace(/\s+/g, ' ').trim()));
  if (cells.length === 0) return '';
  const ncols = Math.max(...cells.map((r) => r.length));
  const header = cells[0];
  const body = cells.slice(1);
  const line = (row) => '| ' + Array.from({ length: ncols }, (_, i) => (row[i] ?? '')).join(' | ') + ' |';
  const sep = '| ' + Array.from({ length: ncols }, () => '---').join(' | ') + ' |';
  return [line(header), sep, ...body.map(line)].join('\n');
}

function relativeLink(fromPage, toPath) {
  // fromPage: content-relative path without extension ('index', 'models',
  // 'guides/usage'). Returns a root-relative-under-base link prefixed with the
  // right number of '..' steps (public assets and pages all resolve from the
  // same root under the Read the Docs base path).
  const up = fromPage === 'index' ? 0 : fromPage.split('/').length;
  return '../'.repeat(up) + toPath;
}

function localImageNameFor(file) {
  const ext = file.split('.').pop().toLowerCase();
  if (ext === 'ini') return `model-data/${file}`;
  return `images/${file}`;
}

function isIpynb(t) { return /\.ipynb$/.test(t); }

function fixTarget(target, fromPage, docsFiles) {
  if (!target || target.startsWith('http') || target.startsWith('/') || target.startsWith('#')) return target;
  if (isIpynb(target) || nbSlugs.has(target)) {
    const slug = target.endsWith('.ipynb') ? basename(target, '.ipynb').replace(/^_/, '') : target;
    return `${relativeLink(fromPage, `notebooks/${slug}`)}/`;
  }
  if (target.startsWith('preprocess-templates')) {
    return `https://github.com/galsci/pysm/tree/main/docs/${target}`;
  }
  if (PAGE_SLUGS.has(target)) {
    return `${relativeLink(fromPage, PAGE_SLUGS.get(target))}/`;
  }
  const base = basename(target);
  if (docsFiles.has(base)) {
    return relativeLink(fromPage, `generated/${localImageNameFor(base)}`);
  }
  return target;
}

function convertToctree(inner, fromPage, docsFiles) {
  const lines = inner.split('\n').map((l) => l.trim()).filter((l) => l && !l.startsWith(':') && !l.startsWith('toctree') && !l.startsWith('..'));
  const items = [];
  for (const entry of lines) {
    const m = entry.match(/^(.+?)\s+<([^>]+)>$/);
    const label = m ? m[1] : entry;
    const target = m ? m[2] : entry;
    items.push(`- [${label}](${fixTarget(target, fromPage, docsFiles)})`);
  }
  return items.join('\n');
}

function demoteHeadings(md) {
  // rst2myst turns every RST top-level section (underlined with '=') into H1.
  // Only the page title (the first heading) may stay at H1; it is later moved
  // to frontmatter. Other H1s (sections like "Tutorials" in the index) become
  // H2. Lower levels are already correct and are left untouched. Fenced code
  // blocks are skipped.
  const lines = md.split('\n');
  let inCode = false;
  let firstHeading = false;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (/^```/.test(line.trim())) {
      inCode = !inCode;
      continue;
    }
    if (inCode) continue;
    const m = line.match(/^# /);
    if (!m) continue;
    if (!firstHeading) {
      firstHeading = true;
      continue;
    }
    lines[i] = '## ' + line.slice(2);
  }
  return lines.join('\n');
}

function postprocess(md, fromPage, docsFiles) {
  let out = md
    .replace(/^\([a-z0-9_-]+\)=\s*$/gm, '')
    .replace(/^([ \t]*)```\{toctree\}\n([\s\S]*?)```/gm, (_, indent, inner) =>
      convertToctree(inner, fromPage, docsFiles)
        .split('\n')
        .map((l) => indent + l)
        .join('\n')
    )
    .replace(/^([ \t]*)```\{eval-rst\}\n([\s\S]*?)```/gm, (_, indent, inner) =>
      convertEvalRst(inner, fromPage, docsFiles)
        .split('\n')
        .map((l) => indent + l)
        .join('\n')
    )
    .replace(/^([ \t]*)```\{image\} ([^\n]+)\n?([\s\S]*?)```/gm, (_, indent, src, opts) => {
      const name = src.trim();
      const altMatch = opts.match(/^\s*(?:alt|name|target):\s*(.+)$/m);
      const alt = altMatch ? altMatch[1].trim() : basename(name).replace(/\.[^.]+$/, '');
      return `${indent}![${alt.replaceAll('"', '\\"')}](${fixTarget(name, fromPage, docsFiles)})`;
    });
  out = cleanInline(out);
  out = out
    .replace(/\{ref\}`([^`]+)`/g, (_, label) => `[${label}](${fixTarget(label, fromPage, docsFiles)})`)
    .replace(/\{doc\}`([^`]+?) <([^>]+)>`/g, (_, title, page) => `[${title}](${fixTarget(page, fromPage, docsFiles)})`)
    .replace(/\{download\}`([^`]+?) <([^>]+)>`/g, (_, label, file) => `[${label}](${fixTarget(file, fromPage, docsFiles)})`)
    .replace(/\\\$([^$\n]{1,200}?)\\\$/g, (_, m) => `$${cleanMath(m)}$`)
    .replace(/\]\(([^)\s]+\.ipynb)\)/g, (_, file) => `](${fixTarget(file, fromPage, docsFiles)})`)
    .replace(/\]\(([^)\s]+)\)/g, (_, target) => {
      const fixed = fixTarget(target, fromPage, docsFiles);
      return fixed === target ? `](${target})` : `](${fixed})`;
    });
  out = demoteHeadings(out);
  // Images that live in public/generated (copied from docs/) cannot go through
  // Astro's markdown image pipeline (it resolves paths against the content
  // file), so emit them as plain HTML <img> with the page-relative URL.
  out = out.replace(/!\[([^\]]*)\]\(([^)]+\.(?:png|jpe?g|jpg))\)/g, (_, alt, target) => {
    if (target.includes('generated/')) {
      return `<img src="${target}" alt="${String(alt).replaceAll('"', '&quot;')}" />`;
    }
    return `![${alt}](${target})`;
  });
  return out;
}

function frontmatter(md, file, overrides = {}) {
  const titleMatch = md.match(/^# (.+)$/m);
  const title = titleMatch ? titleMatch[1].trim() : basename(file, '.md');
  const body = md.replace(/^# .+$/m, '');
  const firstPara = body
    .split('\n')
    .map((l) => l.trim())
    .find((l) => l && !l.startsWith('#') && !l.startsWith('|') && !l.startsWith('`') && !l.startsWith('-'));
  const description = (overrides.description ?? (firstPara ?? '')).slice(0, 160);
  return [
    '---',
    `title: "${(overrides.title ?? title).replaceAll('"', '\\"')}"`,
    `description: "${description.replaceAll('"', '\\"')}"`,
    ...Object.entries(overrides.frontmatter ?? {}).map(([k, v]) => `${k}: ${v}`),
    '---',
    '',
  ].join('\n');
}

// --- Files -------------------------------------------------------------------

function collectRst(dir, prefix = '') {
  const out = [];
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    if (entry.isDirectory() && entry.name !== 'preprocess-templates') {
      out.push(...collectRst(join(dir, entry.name), `${prefix}${entry.name}/`));
    } else if (entry.isFile() && entry.name.endsWith('.rst')) {
      out.push({ rel: `${prefix}${entry.name}`, file: join(dir, entry.name) });
    }
  }
  return out;
}

function docsDataFiles() {
  return readdirSync(docsRoot)
    .filter((f) => /\.(png|jpg|jpeg|ini)$/i.test(f) && statSync(join(docsRoot, f)).isFile());
}

function convertRst(file, workDir) {
  const cwd = dirname(file);
  const uvx = spawnSync('bash', ['-lc', 'command -v uvx >/dev/null 2>&1']);
  if (uvx.status === 0) {
    spawnSync('uvx', ['--from', 'rst-to-myst', 'rst2myst', 'convert', '--no-sphinx', basename(file)], { cwd, stdio: 'ignore' });
  } else {
    spawnSync('rst2myst', ['convert', '--no-sphinx', basename(file)], { cwd, stdio: 'ignore' });
  }
  const mdPath = join(cwd, basename(file).replace(/\.rst$/, '.md'));
  const content = readFileSync(mdPath, 'utf8');
  rmSync(mdPath, { force: true }); // do not leave converted copies in the source tree
  return content;
}

// --- Main --------------------------------------------------------------------

// Remove previously generated doc pages (never the notebooks dir, which is
// owned by generate-notebooks.mjs).
if (existsSync(outRoot)) {
  for (const entry of readdirSync(outRoot, { withFileTypes: true })) {
    if (entry.name === 'notebooks') continue;
    rmSync(join(outRoot, entry.name), { recursive: true, force: true });
  }
}
mkdirSync(outRoot, { recursive: true });
rmSync(publicGen, { recursive: true, force: true });
mkdirSync(publicGen, { recursive: true });

const docsFiles = new Set(docsDataFiles());
const nbSlugs = new Set(
  readdirSync(docsRoot)
    .filter((f) => f.endsWith('.ipynb') && statSync(join(docsRoot, f)).isFile())
    .map((f) => basename(f, '.ipynb').replace(/^_/, ''))
);
for (const f of docsFiles) {
  const ext = f.split('.').pop().toLowerCase();
  const targetDir = join(publicGen, ext === 'ini' ? 'model-data' : 'images');
  mkdirSync(targetDir, { recursive: true });
  cpSync(join(docsRoot, f), join(targetDir, f));
}

const rstFiles = collectRst(docsRoot);
for (const { rel, file } of rstFiles) {
  const pagePath = rel.replace(/\.rst$/, '');
  const workDir = resolve(repoRoot, 'docs', dirname(rel));
  const raw = convertRst(file, workDir);
  const isIndex = pagePath === 'index';
  let body = postprocess(raw, pagePath, docsFiles);
  const titleMatch = body.match(/^# (.+)$/m);
  const firstPara = body
    .replace(/^# .+$/m, '')
    .split('\n')
    .map((l) => l.trim())
    .find((l) => l && !l.startsWith('#') && !l.startsWith('|') && !l.startsWith('`') && !l.startsWith('-'));
  const description = (isIndex ? siteConfig.description : (firstPara ?? '')).slice(0, 160);
  const bodyNoH1 = body.replace(/^# .+$/m, '').trim();

  let content;
  if (isIndex) {
    const heroYaml = [
      'hero:',
      '  title: PySM',
      `  tagline: ${siteConfig.hero.tagline}`,
      '  image:',
      `    alt: ${siteConfig.hero.image.alt}`,
      `    file: ${siteConfig.hero.image.file}`,
      '  actions:',
      ...siteConfig.hero.actions.map((a) => `    - text: ${a.text}\n      link: ${a.link}\n      icon: ${a.icon}`),
    ].join('\n');
    const front = ['---', 'title: "Introduction"', `description: "${description.replaceAll('"', '\\"')}"`, heroYaml, '---', ''].join('\n');
    const cards = siteConfig.cards
      .map((c) => `\t<a class="card-link" href="${c.link}">\n\t\t<Card title="${c.title}" icon="${c.icon}">\n\t\t\t${c.text}\n\t\t</Card>\n\t</a>`)
      .join('\n');
    content = `${front}\nimport { Card, CardGrid } from '@astrojs/starlight/components';\n\n<CardGrid>\n${cards}\n</CardGrid>\n\n${bodyNoH1}\n`;
  } else {
    const front = frontmatter(body, pagePath, { description });
    content = `${front}${bodyNoH1}\n`;
  }
  const outFile = `${outRoot}/${pagePath}${isIndex ? '.mdx' : '.md'}`;
  mkdirSync(dirname(outFile), { recursive: true });
  writeFileSync(outFile, content);
  console.log(`  ${rel} -> ${pagePath}${isIndex ? '.mdx' : '.md'}`);
}

writeFileSync(join(outRoot, '404.md'), notFoundTemplate.trimEnd() + '\n');
console.log('  (template) 404.md');

console.log(`Generated ${rstFiles.length} doc pages and ${docsFiles.size} data files.`);
